# Local copy of _vpaes_preheat for this compilation unit.
# Loads VPAES constant tables into vr9-vr15, vr18.
.align 4
_vpaes_preheat:
    la.local  $a6,Lk_s0F
    vld       $vr10,$a6,-0x20
    vld       $vr11,$a6,-0x10
    vld       $vr9,$a6,0
    vld       $vr13,$a6,0x30
    vld       $vr12,$a6,0x40
    vld       $vr15,$a6,0x50
    vld       $vr14,$a6,0x60
    vldi      $vr18,0
    jirl      $zero,$ra,0

# LASX preheat: load 256-bit (duplicated) constants + Lk_ipt/Lk_sbo + MC tables
.align 4
_vpaes_lasx_preheat_gcm:
    la.local  $a6,Lk_s0F
    vld       $vr10,$a6,-0x20
    xvreplve0.q $xr10,$xr10
    vld       $vr11,$a6,-0x10
    xvreplve0.q $xr11,$xr11
    vld       $vr9,$a6,0
    xvreplve0.q $xr9,$xr9
    vld       $vr13,$a6,0x30
    xvreplve0.q $xr13,$xr13
    vld       $vr12,$a6,0x40
    xvreplve0.q $xr12,$xr12
    vld       $vr15,$a6,0x50
    xvreplve0.q $xr15,$xr15
    vld       $vr14,$a6,0x60
    xvreplve0.q $xr14,$xr14
    xvldi     $xr18,0
    la.local  $r16,Lk_ipt
    vld       $vr27,$r16,0
    xvreplve0.q $xr27,$xr27
    vld       $vr28,$r16,16
    xvreplve0.q $xr28,$xr28
    la.local  $r16,Lk_sbo
    vld       $vr29,$r16,0
    xvreplve0.q $xr29,$xr29
    vld       $vr30,$r16,16
    xvreplve0.q $xr30,$xr30
    # Preload MC forward[0..3] into xvr16,17,19,20
    la.local  $r16,Lk_mc_forward
    vld       $vr16,$r16,0
    xvreplve0.q $xr16,$xr16
    vld       $vr17,$r16,16
    xvreplve0.q $xr17,$xr17
    vld       $vr19,$r16,32
    xvreplve0.q $xr19,$xr19
    vld       $vr20,$r16,48
    xvreplve0.q $xr20,$xr20
    # Preload MC backward[0..3] into xvr21,22,23,24
    la.local  $r16,Lk_mc_backward
    vld       $vr21,$r16,0
    xvreplve0.q $xr21,$xr21
    vld       $vr22,$r16,16
    xvreplve0.q $xr22,$xr22
    vld       $vr23,$r16,32
    xvreplve0.q $xr23,$xr23
    vld       $vr24,$r16,48
    xvreplve0.q $xr24,$xr24
    jirl      $zero,$ra,0

.globl  loongarch64_vpaes_gcm_encrypt
.type   loongarch64_vpaes_gcm_encrypt,@function
.align  4
loongarch64_vpaes_gcm_encrypt:
.cfi_startproc
    beqz    $a2,.Lgcm_enc_ret0

    addi.d  $sp,$sp,-960
    st.d    $ra,$sp,952
    st.d    $fp,$sp,944
    st.d    $s0,$sp,936
    st.d    $s1,$sp,928
    st.d    $s2,$sp,920
    st.d    $s3,$sp,912
    st.d    $s4,$sp,904
    st.d    $s5,$sp,896
    st.d    $s6,$sp,888
    st.d    $s7,$sp,880
    st.d    $s8,$sp,872

    ori     $fp,$a5,0           # Xi*
    ori     $s1,$a3,0           # AES key schedule
    # aligned_len = len & -32
    ori     $s0,$a2,0
    bstrins.d $s0,$zero,4,0
    beqz    $s0,.Lgcm_enc_done

    # Save inp / out / ivec to stack (GPRs will be reused for GHASH)
    st.d    $a0,$sp,816
    st.d    $a1,$sp,824
    st.d    $a4,$sp,840

    st.d    $s0,$sp,856         # save aligned_len for return

    la.local $s2,.Lrem_8bit_shl48
    addi.d  $s3,$fp,32          # Htable base
    ori     $s4,$sp,0           # H shl4 bytes
    addi.d  $s5,$sp,16          # H shr4 table
    addi.d  $s6,$sp,272         # H^2 4-bit table
    addi.d  $s7,$sp,528         # H^2 shl4 bytes
    addi.d  $s8,$sp,544         # H^2 shr4 table

    # Build H 528B helpers.
    ori     $r14,$s3,0
    ori     $r15,$s5,0
    ori     $r16,$s4,0
    li.d    $r20,16
.Lprep_h_528:
    ld.d    $r17,$r14,0
    ld.d    $r18,$r14,8
    andi    $r19,$r18,0x0f
    slli.d  $r19,$r19,4
    st.b    $r19,$r16,0
    slli.d  $r21,$r17,60
    srli.d  $r18,$r18,4
    or      $r18,$r18,$r21
    srli.d  $r17,$r17,4
    st.d    $r17,$r15,0
